//! 🏠️ Literal Home schema and full unsigned64 generation with separately editable words.
use super::SHomeSnapshot;
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Projection,Cell,Reconstruction,NativeEncodingBound}}};
use semio_framework_value::ValueError;
fn invalid(message:impl Into<String>)->ValueError{ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,message)}

impl ArtifactSqliteSnapshot for SHomeSnapshot{
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,ValueError>{control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;control.check_rows(1)?;store::encode_sqlite_snapshot_record_native(encoding,"s.home",Self::__dsl_spec_producer(),|native|self.__dsl_to_record_controlled(native),control)}
 fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{control.checkpoint(SqliteSnapshotPhase::DecodeNative,0,0)?;control.check_rows(1)?;store::decode_sqlite_snapshot_record_native(payload,"s.home",Self::__dsl_spec_producer(),|record,native|Self::__dsl_from_record_controlled(record,native),control)}
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let mut bound=NativeEncodingBound::new(control)?;bound.add(4096)?;bound.repeated(self.schema.len(),6)?;bound.finish()}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;control.check_rows(1)?;control.check_value_bytes(self.schema.len().checked_add(24).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"Home value byte count overflow"))?)?;let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.insert_key("home_document",1,&[Cell::Text(&self.schema),Cell::Integer((self.catalog_generation>>32)as i64),Cell::Integer((self.catalog_generation&0xffffffff)as i64)])?;p.finish()}
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits())?;if database.tables.len()!=1{return Err(invalid("Home requires its one literal table"))}let row=database.table("home_document")?.single_row()?;if row.values.len()!=4||row.integer(0)?!=row.rowid{return Err(invalid("Home document identity differs"))}let(high,low)=(row.integer(2)?,row.integer(3)?);if !(0..=u32::MAX as i64).contains(&high)||!(0..=u32::MAX as i64).contains(&low){return Err(invalid("Home generation word exceeds unsigned32"))}let mut owned=Reconstruction::new(control)?;owned.scalar()?;let schema=owned.text(row.text(1)?)?;owned.checkpoint()?;Ok(Self{schema,catalog_generation:((high as u64)<<32)|(low as u64)})}
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::io_schema::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0).map_err(store::io_schema::IoError::from_value_error)?;if dialect.artifact_kind!="s.space.home"||dialect.standard!="1"||dialect.subset!="*"{return Err(store::io_schema::IoError::from_value_error(invalid("Home does not own this semantic subset")))}if Self::from_sqlite_database(database,control).map_err(store::io_schema::IoError::from_value_error)?!=*self{return Err(store::io_schema::IoError::from_value_error(invalid("Home owned state differs")))}Ok(store::io_schema::IoOutcome::clean(()))}
}
